import type { StyleSpecification } from 'maplibre-gl';
import style from './map-style.json';

/**
 * The self-hosted map (docker/maps/README.md): tiles, glyphs and sprites are all same-origin under
 * /maps/. The style is generated by `npm run maps:style`; components never add map URLs of their own.
 *
 * Zoom levels are MapLibre's (512 px tiles), one below the usual 256 px web map levels of the same scale.
 */
export const mapConfig = {
    style: style as unknown as StyleSpecification,
    minZoom: 0,
    // Highest zoom of the production dataset; MapLibre overzooms the last level it has.
    maxZoom: 12,
    world: { center: { latitude: 30, longitude: 10 }, zoom: 1 },
} as const;
